+// appendQuote is a faster version of strconv.AppendQuote for our use case.
+func appendQuote(dst []byte, s string) []byte {
+	dst = append(dst, '"')
+	start := 0
+	for i := 0; i < len(s); i++ {
+		c := s[i]
+		if c == '\\' || c == '"' {
+			dst = append(dst, s[start:i]...)
+			dst = append(dst, '\\', c)
+			start = i + 1
+		} else if c < 0x20 || c == 0x7f {
+			dst = append(dst, s[start:i]...)
+			dst = append(dst, '\\')
+			switch c {
+			case '\n':
+				dst = append(dst, 'n')
+			case '\r':
+				dst = append(dst, 'r')
+			case '\t':
+				dst = append(dst, 't')
+			default:
+				dst = append(dst, 'x', "0123456789abcdef"[c>>4], "0123456789abcdef"[c&0xf])
+			}
+			start = i + 1
+		}
