+func (node *VectorSelector) atModifiers() (string, string) {
+	offset := ""
+	switch {
+	case node.OriginalOffsetExpr != nil:
+		offset = " offset " + node.OriginalOffsetExpr.String()
+	case node.OriginalOffset > 0:
+		offset = " offset " + model.Duration(node.OriginalOffset).String()
+	case node.OriginalOffset < 0:
+		offset = " offset -" + model.Duration(-node.OriginalOffset).String()
+	}
+	at := ""
+	switch {
+	case node.Timestamp != nil:
+		at = fmt.Sprintf(" @ %.3f", float64(*node.Timestamp)/1000.0)
+	case node.StartOrEnd == START:
+		at = " @ start()"
+	case node.StartOrEnd == END:
+		at = " @ end()"
+	}
+	return at, offset
+}

